;/* stats.js */
window.pct = function(n, d) {
  return d === 0 ? 0 : Math.round((n / d) * 100);
};
window.avg = function(arr) {
  return arr.length === 0 ? 0 : (arr.reduce((a, b) => a + b, 0) / arr.length).toFixed(1);
};
window.getMatchDeck = function(d) {
  if (!d) return 'Desconhecido';
  if (d.Arquetipo) return d.Subtipo ? `${d.Arquetipo} (${d.Subtipo})` : d.Arquetipo;
  return d.Deck || 'Desconhecido';
};
window.getMatchOppDeck = function(d) {
  if (!d) return 'Desconhecido';
  if (d.DeckAdvArquetipo) return d.SubtipoAdv ? `${d.DeckAdvArquetipo} (${d.SubtipoAdv})` : d.DeckAdvArquetipo;
  return d.DeckAdv || 'Desconhecido';
};
window.groupBy = function(data, keyOrFn) {
  const fn = typeof keyOrFn === 'function' ? keyOrFn : item => item[keyOrFn];
  return data.reduce((acc, item) => {
    const key = fn(item) ?? 'Outros';
    if (!acc[key]) acc[key] = [];
    acc[key].push(item);
    return acc;
  }, {});
};
window.isBricked = function(r) {
  if (!r) return false;
  if (r.GamesDetail && Array.isArray(r.GamesDetail) && r.GamesDetail.length > 0) {
    return r.GamesDetail.some(g => g.brick === 'Sim');
  }
  return r.Brick === 'Sim' || (r.Brick && r.Brick !== 'Nenhum' && r.Brick !== 'Não');
};
window.calculateStats = function(matches) {
  if (!Array.isArray(matches) || matches.length === 0) {
    return { wins: 0, draws: 0, losses: 0, total: 0, wr: 0, brickWins: 0, totalBricks: 0, totalGamesCount: 0, totalGameBricksCount: 0 };
  }
  const total  = matches.length;
  const wins   = matches.filter(m => m.Resultado === 'Vitória').length;
  const draws  = matches.filter(m => m.Resultado === 'Empate').length;
  const losses = matches.filter(m => m.Resultado === 'Derrota').length;
  const wr     = pct(wins, total);
  const brickMatches = matches.filter(m => isBricked(m));
  const brickWins    = brickMatches.filter(m => m.Resultado === 'Vitória').length;
  let totalGamesCount = 0;
  let totalGameBricksCount = 0;
  matches.forEach(m => {
    if (m.GamesDetail && Array.isArray(m.GamesDetail) && m.GamesDetail.length > 0) {
      totalGamesCount += m.GamesDetail.length;
      totalGameBricksCount += m.GamesDetail.filter(g => g.brick === 'Sim').length;
    } else {
      totalGamesCount += 1;
      if (isBricked(m)) totalGameBricksCount += 1;
    }
  });
  return {
    wins,
    draws,
    losses,
    total,
    wr,
    brickWins,
    totalBricks: brickMatches.length,
    totalGamesCount,
    totalGameBricksCount
  };
};

;/* mirror.js */
window.invertPlacar = function(placar) {
  if (!placar || typeof placar !== 'string' || !placar.includes('-')) return placar;
  const parts = placar.split('-');
  if (parts.length !== 2) return placar;
  return `${parts[1].trim()}-${parts[0].trim()}`;
};
window.buildMirrorMatch = function(primaryMatch) {
  if (!primaryMatch || !primaryMatch.Adversario) return null;
  const currentPlayers = typeof loadPlayers === 'function' ? loadPlayers() : (window.players || []);
  const advNameLower = primaryMatch.Adversario.trim().toLowerCase();
  const isTeamMember = currentPlayers.some(p => p.trim().toLowerCase() === advNameLower);
  if (!isTeamMember) return null;
  if (primaryMatch.Player && primaryMatch.Player.trim().toLowerCase() === advNameLower) {
    return null;
  }
  const teamPlayerName = currentPlayers.find(p => p.trim().toLowerCase() === advNameLower) || primaryMatch.Adversario.trim();
  let mirrorRes = 'Empate';
  let mirrorPontos = 0.5;
  if (primaryMatch.Resultado === 'Vitória') {
    mirrorRes = 'Derrota';
    mirrorPontos = 0;
  } else if (primaryMatch.Resultado === 'Derrota') {
    mirrorRes = 'Vitória';
    mirrorPontos = 1;
  }
  const mirrorPlacar = invertPlacar(primaryMatch.Placar);
  let mirrorGamesDetail = null;
  let mirrorStart = primaryMatch.Start === '1º' ? '2º' : primaryMatch.Start === '2º' ? '1º' : primaryMatch.Start;
  let mirrorBrick = primaryMatch.BrickOp || 'Não';
  let mirrorBrickOp = primaryMatch.Brick || 'Não';
  if (primaryMatch.GamesDetail && Array.isArray(primaryMatch.GamesDetail) && primaryMatch.GamesDetail.length > 0) {
    mirrorGamesDetail = primaryMatch.GamesDetail.map(g => ({
      game: g.game,
      start: g.start === '1º' ? '2º' : g.start === '2º' ? '1º' : g.start,
      brick: g.brickOp || 'Não',
      brickOp: g.brick || 'Não'
    }));
    mirrorStart = mirrorGamesDetail.map(g => g.start).join(', ');
    mirrorBrick = mirrorGamesDetail.some(g => g.brick === 'Sim') ? 'Sim' : 'Não';
    mirrorBrickOp = mirrorGamesDetail.some(g => g.brickOp === 'Sim') ? 'Sim' : 'Não';
  }
  let mirrorId = primaryMatch._mirrorId;
  if (!mirrorId) {
    const baseNum = Number(primaryMatch.id);
    mirrorId = (!isNaN(baseNum) && baseNum > 0) ? (baseNum + 1).toString() : (Date.now() + 1).toString();
  }
  return {
    id:               mirrorId,
    _mirroredFrom:    primaryMatch.id,
    Data:             primaryMatch.Data,
    Player:           teamPlayerName,
    Deck:             primaryMatch.DeckAdv,
    Arquetipo:        primaryMatch.DeckAdvArquetipo || primaryMatch.DeckAdv,
    Subtipo:          primaryMatch.SubtipoAdv || '',
    Adversario:       primaryMatch.Player,
    DeckAdv:          primaryMatch.Deck,
    DeckAdvArquetipo: primaryMatch.Arquetipo || primaryMatch.Deck,
    SubtipoAdv:       primaryMatch.Subtipo || '',
    Luck:             primaryMatch.Luck || 0,
    Formato:          primaryMatch.Formato || 'MD1',
    Start:            mirrorStart,
    Resultado:        mirrorRes,
    Pontos:           mirrorPontos,
    Placar:           mirrorPlacar,
    Local:            primaryMatch.Local || '—',
    Colecao:          primaryMatch.Colecao || '—',
    Brick:            mirrorBrick,
    BrickOp:          mirrorBrickOp,
    Confiabilidade:   primaryMatch.Confiabilidade || 'Alta',
    GamesDetail:      mirrorGamesDetail,
    ListaMeuDeck:     primaryMatch.ListaDeckAdv || '',
    ListaDeckAdv:     primaryMatch.ListaMeuDeck || '',
    Comentarios:      primaryMatch.Comentarios ? `[Espelho vs ${primaryMatch.Player}] ${primaryMatch.Comentarios}` : `Partida interna vs ${primaryMatch.Player}`,
    _manual:          true
  };
};
window.syncAllTeamMirrorMatches = function() {
  const currentPlayers = typeof loadPlayers === 'function' ? loadPlayers() : (window.players || []);
  if (!Array.isArray(currentPlayers) || currentPlayers.length === 0) return;
  let manual = typeof loadManual === 'function' ? loadManual() : [];
  let updated = false;
  for (let i = 0; i < manual.length; i++) {
    const m = manual[i];
    if (m._mirroredFrom) continue;
    const mirror = buildMirrorMatch(m);
    if (!mirror) continue;
    const exists = manual.some(ex => 
      ex.id === mirror.id || 
      ex._mirroredFrom === m.id || 
      m._mirrorId === ex.id ||
      (ex.Player.toLowerCase() === mirror.Player.toLowerCase() &&
       ex.Adversario.toLowerCase() === mirror.Adversario.toLowerCase() &&
       ex.Data === mirror.Data &&
       ex.Deck === mirror.Deck)
    );
    if (!exists) {
      m._mirrorId = mirror.id;
      manual.push(mirror);
      updated = true;
    }
  }
  if (updated && typeof saveManual === 'function') {
    saveManual(manual);
  }
};

;/* md3.js */
window.getGameCountFromPlacar = function(formato, placar, userOverriddenCount = null) {
  if (formato !== 'MD3') return 1;
  const cleanPlacar = (placar || '').trim();
  if (userOverriddenCount) {
    if ((cleanPlacar === '1-0' || cleanPlacar === '0-1') && (userOverriddenCount === 1 || userOverriddenCount === 2)) {
      return userOverriddenCount;
    }
    if (cleanPlacar === '1-1' && (userOverriddenCount === 2 || userOverriddenCount === 3)) {
      return userOverriddenCount;
    }
  }
  if (cleanPlacar === '0-0') return 1;
  if (cleanPlacar === '1-0' || cleanPlacar === '0-1') return 1;
  if (cleanPlacar === '1-1') return 2;
  if (cleanPlacar === '2-0' || cleanPlacar === '0-2') return 2;
  if (cleanPlacar === '2-1' || cleanPlacar === '1-2') return 3;
  return 2;
};
window.renderMD3GamesUI = function(existingGamesDetail = null, userCountOverride = null) {
  const formato = document.getElementById('formMatchFormato')?.value || 'MD1';
  const placar = document.getElementById('formMatchPlacar')?.value || '';
  const container = document.getElementById('md3GamesSection');
  const grid = document.getElementById('md3GamesGrid');
  const toggleWrap = document.getElementById('md3GamesToggleWrap');
  const singleStartGroup = document.getElementById('formMatchStart')?.parentElement;
  const singleBrickGroup = document.getElementById('singleMatchBrickGroup');
  const singleBrickOpGroup = document.getElementById('singleMatchBrickOpGroup');
  if (!container || !grid) return;
  if (formato !== 'MD3') {
    container.style.display = 'none';
    if (singleStartGroup) singleStartGroup.style.display = '';
    if (singleBrickGroup) singleBrickGroup.style.display = '';
    if (singleBrickOpGroup) singleBrickOpGroup.style.display = '';
    return;
  }
  container.style.display = 'block';
  if (singleStartGroup) singleStartGroup.style.display = 'none';
  if (singleBrickGroup) singleBrickGroup.style.display = 'none';
  if (singleBrickOpGroup) singleBrickOpGroup.style.display = 'none';
  let count = userCountOverride || (existingGamesDetail && existingGamesDetail.length ? existingGamesDetail.length : getGameCountFromPlacar('MD3', placar));
  window._activeMD3GameCount = count;
  if (toggleWrap) {
    const cleanPlacar = (placar || '').trim();
    if (cleanPlacar === '1-0' || cleanPlacar === '0-1') {
      toggleWrap.style.display = 'block';
      toggleWrap.innerHTML = `
        <label class="form-label" style="font-size:0.75rem; color:var(--text2); margin-bottom:0.3rem;">🎮 Quantidade de Games Jogados:</label>
        <div style="display:flex; gap:0.4rem;">
          <button type="button" class="pill-btn ${count === 1 ? 'active-start' : ''}" style="flex:1;" onclick="renderMD3GamesUI(null, 1)">1 Game (Placar Normal)</button>
          <button type="button" class="pill-btn ${count === 2 ? 'active-start' : ''}" style="flex:1;" onclick="renderMD3GamesUI(null, 2)">2 Games (Game 2 não finalizou)</button>
        </div>
      `;
    } else if (cleanPlacar === '1-1') {
      toggleWrap.style.display = 'block';
      toggleWrap.innerHTML = `
        <label class="form-label" style="font-size:0.75rem; color:var(--text2); margin-bottom:0.3rem;">🎮 Quantidade de Games Jogados:</label>
        <div style="display:flex; gap:0.4rem;">
          <button type="button" class="pill-btn ${count === 2 ? 'active-start' : ''}" style="flex:1;" onclick="renderMD3GamesUI(null, 2)">2 Games (Empate nos 2 games)</button>
          <button type="button" class="pill-btn ${count === 3 ? 'active-start' : ''}" style="flex:1;" onclick="renderMD3GamesUI(null, 3)">3 Games (Game 3 não finalizou)</button>
        </div>
      `;
    } else {
      toggleWrap.style.display = 'none';
      toggleWrap.innerHTML = '';
    }
  }
  grid.innerHTML = '';
  for (let i = 1; i <= count; i++) {
    const prev = (existingGamesDetail && existingGamesDetail[i - 1]) || {};
    const defaultStart = prev.start || (i % 2 === 1 ? '1º' : '2º');
    const defaultBrick = prev.brick || 'Não';
    const defaultBrickOp = prev.brickOp || 'Não';
    const card = document.createElement('div');
    card.className = 'md3-game-card';
    card.style.cssText = 'background: var(--bg3); border: 1px solid var(--border); border-radius: 8px; padding: 0.8rem; margin-top: 0.5rem;';
    card.innerHTML = `
      <div style="font-weight: 700; font-size: 0.85rem; color: var(--accent2); margin-bottom: 0.6rem; display: flex; justify-content: space-between; align-items: center;">
        <span>🎮 Game ${i}</span>
      </div>
      <div class="form-row three-col" style="gap: 0.6rem;">
        <div class="form-group">
          <label class="form-label" style="font-size:0.75rem;">🎲 Start</label>
          <select class="form-select sm" id="md3GameStart_${i}">
            <option value="1º" ${defaultStart === '1º' ? 'selected' : ''}>1º a Jogar</option>
            <option value="2º" ${defaultStart === '2º' ? 'selected' : ''}>2º a Jogar</option>
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" style="font-size:0.75rem;">💥 Brickei?</label>
          <select class="form-select sm" id="md3GameBrick_${i}">
            <option value="Não" ${defaultBrick === 'Não' ? 'selected' : ''}>Não</option>
            <option value="Sim" ${defaultBrick === 'Sim' ? 'selected' : ''}>Sim</option>
          </select>
        </div>
        <div class="form-group">
          <label class="form-label" style="font-size:0.75rem;">💥 Opp Brickou?</label>
          <select class="form-select sm" id="md3GameBrickOp_${i}">
            <option value="Não" ${defaultBrickOp === 'Não' ? 'selected' : ''}>Não</option>
            <option value="Sim" ${defaultBrickOp === 'Sim' ? 'selected' : ''}>Sim</option>
          </select>
        </div>
      </div>
    `;
    grid.appendChild(card);
  }
};

;/* quicklog.js */
window.quickLogPillState = {};
window.renderQuickLogTouchPills = function() {
  const formato = document.getElementById('quickLogFormato')?.value || 'MD1';
  const placar = document.getElementById('quickLogPlacar')?.value || '1-0';
  const grid = document.getElementById('quickLogPillGrid');
  const countLabel = document.getElementById('quickLogGamesCountLabel');
  const startSelectGroup = document.getElementById('quickLogStartGroup');
  if (!grid) return;
  if (startSelectGroup) {
    startSelectGroup.style.display = formato === 'MD3' ? 'none' : 'block';
  }
  const gameCount = typeof getGameCountFromPlacar === 'function' ? getGameCountFromPlacar(formato, placar) : (formato === 'MD3' ? 2 : 1);
  if (countLabel) {
    countLabel.textContent = formato === 'MD3' ? `(${gameCount} Game${gameCount > 1 ? 's' : ''})` : `(MD1 - 1 Game)`;
  }
  grid.innerHTML = '';
  for (let i = 1; i <= gameCount; i++) {
    if (!window.quickLogPillState[i]) {
      window.quickLogPillState[i] = {
        start: i % 2 === 1 ? '1º' : '2º',
        brick: 'Não',
        brickOp: 'Não'
      };
    }
    const st = window.quickLogPillState[i];
    const row = document.createElement('div');
    row.className = 'pill-game-row';
    row.innerHTML = `
      <div class="pill-game-header">
        <span>🎮 Game ${i}</span>
      </div>
      <div class="pill-btn-group">
        <button type="button" class="pill-btn ${st.start === '1º' ? 'active-start' : ''}" onclick="toggleQuickLogPill(${i}, 'start')">
          🎲 ${st.start === '1º' ? '1º a Jogar' : '2º a Jogar'}
        </button>
        <button type="button" class="pill-btn ${st.brick === 'Sim' ? 'active-brick' : ''}" onclick="toggleQuickLogPill(${i}, 'brick')">
          💥 Meu: ${st.brick === 'Sim' ? 'Brick' : 'OK'}
        </button>
        <button type="button" class="pill-btn ${st.brickOp === 'Sim' ? 'active-brick' : ''}" onclick="toggleQuickLogPill(${i}, 'brickOp')">
          💥 Opp: ${st.brickOp === 'Sim' ? 'Brick' : 'OK'}
        </button>
      </div>
    `;
    grid.appendChild(row);
  }
};
window.toggleQuickLogPill = function(gameNum, field) {
  if (!window.quickLogPillState[gameNum]) return;
  const current = window.quickLogPillState[gameNum][field];
  if (field === 'start') {
    window.quickLogPillState[gameNum].start = current === '1º' ? '2º' : '1º';
  } else if (field === 'brick') {
    window.quickLogPillState[gameNum].brick = current === 'Sim' ? 'Não' : 'Sim';
  } else if (field === 'brickOp') {
    window.quickLogPillState[gameNum].brickOp = current === 'Sim' ? 'Não' : 'Sim';
  }
  renderQuickLogTouchPills();
};
